interfaces.content:
/**
 * Primitive cell values supported by the spreadsheet engine.
 */
export type CellValue = number | string | boolean | null;

/**
 * Standard spreadsheet error literal strings.
 */
export type CellError = "#DIV/0!" | "#N/A" | "#REF!" | "#VALUE!" | "#NAME?" | "#NUM!" | "#CIRC!";

/**
 * Error codes thrown by parser and evaluation limits.
 */
export type FormulaErrorCode =
  | "FORMULA_TOO_LONG"
  | "EXPRESSION_TOO_DEEP"
  | "CELL_LIMIT_EXCEEDED"
  | "SYNTAX_ERROR"
  | "CIRCULAR_REFERENCE"
  | "UNKNOWN_FUNCTION";

/**
 * Custom error class for formula parsing and execution errors.
 */
export declare class FormulaError extends Error {
  readonly code: FormulaErrorCode;
  constructor(code: FormulaErrorCode, message?: string);
}

/**
 * Coordinate representing a single cell location.
 */
export interface CellCoord {
  readonly sheet?: string;
  readonly row: number;
  readonly col: number;
  readonly rowAbsolute?: boolean;
  readonly colAbsolute?: boolean;
}

/**
 * Rectangular range of cells.
 */
export interface CellRange {
  readonly sheet?: string;
  readonly start: CellCoord;
  readonly end: CellCoord;
}

import type { CellCoord, CellRange, CellValue } from "./types";

export type ASTNodeType =
  | "Literal"
  | "Reference"
  | "Range"
  | "UnaryExpression"
  | "BinaryExpression"
  | "FunctionCall";

export interface ASTNodeBase {
  readonly type: ASTNodeType;
}

export interface LiteralNode extends ASTNodeBase {
  readonly type: "Literal";
  readonly value: CellValue;
}

export interface ReferenceNode extends ASTNodeBase {
  readonly type: "Reference";
  readonly coord: CellCoord;
  readonly raw: string;
}

export interface RangeNode extends ASTNodeBase {
  readonly type: "Range";
  readonly range: CellRange;
  readonly raw: string;
}

export interface UnaryExpressionNode extends ASTNodeBase {
  readonly type: "UnaryExpression";
  readonly operator: "+" | "-";
  readonly argument: ASTNode;
}

export interface BinaryExpressionNode extends ASTNodeBase {
  readonly type: "BinaryExpression";
  readonly operator: "+" | "-" | "*" | "/" | "^" | "%" | "&" | "=" | "<>" | "<" | "<=" | ">" | ">=";
  readonly left: ASTNode;
  readonly right: ASTNode;
}

export interface FunctionCallNode extends ASTNodeBase {
  readonly type: "FunctionCall";
  readonly name: string;
  readonly arguments: ASTNode[];
}

export type ASTNode =
  | LiteralNode
  | ReferenceNode
  | RangeNode
  | UnaryExpressionNode
  | BinaryExpressionNode
  | FunctionCallNode;

export interface ParserOptions {
  maxFormulaLength?: number;
  maxExpressionDepth?: number;
}

export declare function parseFormula(formula: string, options?: ParserOptions): ASTNode;
export declare function parseCellReference(ref: string): CellCoord;
export declare function parseRangeReference(rangeRef: string): CellRange;
export declare function formatCellReference(coord: CellCoord): string;
export declare function extractReferences(ast: ASTNode): string[];

import type { CellError, CellValue } from "./types";

export interface FunctionContext {
  readonly excel1900LeapBug?: boolean;
  getCellValue(ref: string): CellValue | CellError;
  getRangeValues(rangeRef: string): (CellValue | CellError)[][];
}

export type FunctionImplementation = (
  args: any[],
  context: FunctionContext,
) => CellValue | CellError;

export interface IFunctionRegistry {
  register(name: string, fn: FunctionImplementation): void;
  get(name: string): FunctionImplementation | undefined;
  has(name: string): boolean;
  names(): string[];
}

export declare function createDefaultFunctionRegistry(): IFunctionRegistry;
export declare function evaluateFunction(
  name: string,
  args: any[],
  context: FunctionContext,
  registry?: IFunctionRegistry,
): CellValue | CellError;

export interface RecalculationPlan {
  readonly order: string[];
  readonly cycleCells: string[];
}

export interface IDependencyGraph {
  addCell(cell: string): void;
  removeCell(cell: string): void;
  setDependencies(cell: string, dependencies: string[]): void;
  getDependencies(cell: string): string[];
  getDependents(cell: string): string[];
  detectCycle(startCell: string): string[] | null;
  getEvaluationOrder(dirtyCells: string[]): RecalculationPlan;
  hasCell(cell: string): boolean;
  clear(): void;
}

export declare class DependencyGraph implements IDependencyGraph {
  constructor();
  addCell(cell: string): void;
  removeCell(cell: string): void;
  setDependencies(cell: string, dependencies: string[]): void;
  getDependencies(cell: string): string[];
  getDependents(cell: string): string[];
  detectCycle(startCell: string): string[] | null;
  getEvaluationOrder(dirtyCells: string[]): RecalculationPlan;
  hasCell(cell: string): boolean;
  clear(): void;
}

import type { CellError, CellValue } from "./types";

export interface WorkbookOptions {
  maxFormulaLength?: number;
  maxExpressionDepth?: number;
  maxCellCount?: number;
  excel1900LeapBug?: boolean;
}

export interface SetCellResult {
  evaluated: string[];
}

export interface RecalculateResult {
  evaluatedCount: number;
  dirtyCount: number;
}

export interface IWorkbook {
  setCell(ref: string, content: CellValue): SetCellResult;
  getValue(ref: string): CellValue | CellError;
  getDependents(ref: string): string[];
  getCycle(ref: string): string[] | null;
  recalculate(dirtyCells?: string[]): RecalculateResult;
  registerFunction(name: string, fn: (...args: any[]) => CellValue): void;
  toJSON(): Record<string, CellValue>;
  loadJSON(data: Record<string, CellValue>): void;
}

export declare class Workbook implements IWorkbook {
  constructor(opts?: WorkbookOptions);
  setCell(ref: string, content: CellValue): SetCellResult;
  getValue(ref: string): CellValue | CellError;
  getDependents(ref: string): string[];
  getCycle(ref: string): string[] | null;
  recalculate(dirtyCells?: string[]): RecalculateResult;
  registerFunction(name: string, fn: (...args: any[]) => CellValue): void;
  toJSON(): Record<string, CellValue>;
  loadJSON(data: Record<string, CellValue>): void;
}

export interface CLIOutput {
  stdout: { write(s: string): void };
  stderr: { write(s: string): void };
}

export declare function run(argv: string[], io: CLIOutput): Promise<number>;
